<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import UiStatePanel from'./UiStatePanel.vue';import ConfirmDialog from'./ConfirmDialog.vue';import'../credential-assets.css';type State='loading'|'ready'|'empty'|'error'|'expired'|'forbidden'|'blocked';interface Asset{id:string;provider_id:string;name:string;kind:string;status:'active'|'revoked';key_version:string;fingerprint:string;expires_at:string|null;rotated_at:string|null;version:number;updated_at:string}interface Profile{id:string;provider_id:string;credential_asset_id:string;code:string;name:string;browser_family:'chromium';locale:string;timezone:string;status:string;version:number;updated_at:string}interface Provider{id:string;code:string;name:string}const props=defineProps<{apiBaseUrl:string}>(),state=ref<State>('loading'),assets=ref<Asset[]>([]),profiles=ref<Profile[]>([]),providers=ref<Provider[]>([]),requestId=ref(''),message=ref(''),editor=ref<'asset'|'rotate'|'profile'|null>(null),selected=ref<Asset|null>(null),revokeTarget=ref<Asset|null>(null),saving=ref(false),assetForm=reactive({provider_id:'',name:'',kind:'api_key',encoding:'utf8',value:'',expires_at:''}),profileForm=reactive({provider_id:'',credential_asset_id:'',code:'',name:'',browser_family:'chromium',locale:'en-US',timezone:'America/Los_Angeles',status:'disabled'});const failure=(s:number):State=>s===401?'expired':s===403?'forbidden':[408,425,429,502,503,504].includes(s)?'blocked':'error',browserAssets=computed(()=>assets.value.filter(item=>item.kind==='browser_profile'&&item.status==='active'));async function get(path:string){const r=await fetch(`${props.apiBaseUrl}${path}`,{credentials:'include',headers:{accept:'application/json'}}),b=await r.json().catch(()=>null);requestId.value=b?.request_id??requestId.value;if(!r.ok)throw{status:r.status};return b.data;}async function load(){state.value='loading';message.value='';try{[assets.value,profiles.value,providers.value]=await Promise.all([get('/platform/credential-assets'),get('/platform/crawler-profiles'),get('/platform/credential-provider-options')]);state.value=assets.value.length||profiles.value.length?'ready':'empty';}catch(error:any){state.value=failure(error?.status??503);}}function openAsset(){editor.value='asset';selected.value=null;message.value='';Object.assign(assetForm,{provider_id:providers.value[0]?.id??'',name:'',kind:'api_key',encoding:'utf8',value:'',expires_at:''});}function openRotate(asset:Asset){editor.value='rotate';selected.value=asset;message.value='';assetForm.value='';assetForm.encoding='utf8';}function openProfile(){editor.value='profile';selected.value=null;message.value='';const candidate=browserAssets.value[0];Object.assign(profileForm,{provider_id:candidate?.provider_id??providers.value[0]?.id??'',credential_asset_id:candidate?.id??'',code:'',name:'',browser_family:'chromium',locale:'en-US',timezone:'America/Los_Angeles',status:'disabled'});}async function write(path:string,body:unknown){saving.value=true;message.value='';try{const r=await fetch(`${props.apiBaseUrl}${path}`,{method:'POST',credentials:'include',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify(body)}),b=await r.json().catch(()=>null);requestId.value=b?.request_id??'';if(!r.ok){message.value=b?.error?.action_hint??'操作未完成';return false;}return true;}catch{message.value='依赖不可用，未写入';return false;}finally{saving.value=false;assetForm.value='';}}async function saveAsset(){const ok=editor.value==='rotate'&&selected.value?await write(`/platform/credential-assets/${selected.value.id}/rotate`,{secret_payload:{encoding:assetForm.encoding,value:assetForm.value},expected_version:selected.value.version}):await write('/platform/credential-assets',{provider_id:assetForm.provider_id,name:assetForm.name,kind:assetForm.kind,secret_payload:{encoding:assetForm.encoding,value:assetForm.value},expires_at:assetForm.expires_at?new Date(assetForm.expires_at).toISOString():null});if(ok){editor.value=null;selected.value=null;await load();}}async function saveProfile(){if(await write('/platform/crawler-profiles',profileForm)){editor.value=null;await load();}}async function revoke(){const target=revokeTarget.value;if(!target)return;if(await write(`/platform/credential-assets/${target.id}/revoke`,{expected_version:target.version,reason:'平台安全管理员确认撤销'})){revokeTarget.value=null;await load();}}onMounted(load);
</script>
<template><section class="credential-center"><header><div><p>CREDENTIAL VAULT / PLATFORM SECURITY</p><h2>凭证与浏览器档案</h2><span>页面只显示指纹、版本与状态；秘密载荷不会回显。</span></div><div><button type="button" @click="openProfile">＋ 浏览器档案</button><button type="button" class="primary" @click="openAsset">＋ 凭证资产</button></div></header><UiStatePanel v-if="!['ready','empty'].includes(state)" :kind="state" :request-id="requestId" @primary="load"/><section v-else><div class="credential-metrics"><article><small>ACTIVE ASSETS</small><strong>{{assets.filter(x=>x.status==='active').length}}</strong><span>AES-256-GCM</span></article><article><small>CRAWLER PROFILES</small><strong>{{profiles.length}}</strong><span>授权任务才可临时解密</span></article><article><small>PLAINTEXT EXPOSURE</small><strong>0</strong><span>API 不提供读取接口</span></article></div><section v-if="!assets.length" class="credential-empty"><h3>还没有平台凭证资产</h3><p>先选择已登记 Provider，再写入受 AES-256-GCM 保护的秘密载荷。</p><button type="button" @click="openAsset">创建第一个凭证</button></section><div v-else class="credential-grid"><article v-for="asset in assets" :key="asset.id" :data-status="asset.status"><header><span aria-hidden="true">{{asset.kind==='browser_profile'?'▣':'⌘'}}</span><div><small>{{asset.kind}}</small><h3>{{asset.name}}</h3></div><b>{{asset.status}}</b></header><dl><div><dt>指纹</dt><dd><code>{{asset.fingerprint}}</code></dd></div><div><dt>密钥版本</dt><dd>{{asset.key_version}}</dd></div><div><dt>资产版本</dt><dd>v{{asset.version}}</dd></div><div><dt>最近轮换</dt><dd>{{asset.rotated_at?asset.rotated_at.slice(0,10):'尚未轮换'}}</dd></div></dl><footer><button type="button" :disabled="asset.status==='revoked'" @click="openRotate(asset)">轮换载荷</button><button type="button" class="danger" :disabled="asset.status==='revoked'" @click="revokeTarget=asset">撤销</button></footer></article></div><section class="profile-list"><header><div><p>CRAWLER PROFILES</p><h3>浏览器档案引用</h3></div><span>仅保存元数据和受控凭证引用</span></header><article v-for="profile in profiles" :key="profile.id"><strong>{{profile.name}}</strong><code>{{profile.code}}</code><span>{{profile.locale}} · {{profile.timezone}}</span><b>{{profile.status}}</b></article><p v-if="!profiles.length">暂无浏览器档案；不会创建模拟档案。</p></section></section><form v-if="editor==='asset'||editor==='rotate'" class="credential-editor" @submit.prevent="saveAsset"><header><div><p>{{editor==='rotate'?'ROTATE SECRET':'NEW ENCRYPTED ASSET'}}</p><h3>{{editor==='rotate'?`轮换 ${selected?.name}`:'创建凭证资产'}}</h3></div><button type="button" @click="editor=null;assetForm.value=''">×</button></header><div class="credential-fields"><label v-if="editor==='asset'">Provider<select v-model="assetForm.provider_id" required><option value="" disabled>选择来源</option><option v-for="p in providers" :key="p.id" :value="p.id">{{p.name}} · {{p.code}}</option></select></label><label v-if="editor==='asset'">名称<input v-model="assetForm.name" required></label><label v-if="editor==='asset'">类型<select v-model="assetForm.kind"><option v-for="v in ['api_key','account_secret','cookie_bundle','private_key','browser_profile']" :key="v">{{v}}</option></select></label><label>编码<select v-model="assetForm.encoding"><option>utf8</option><option>base64</option></select></label><label class="secret">秘密载荷<input v-model="assetForm.value" type="password" required autocomplete="new-password"><small>仅本次写入；保存后立即从页面状态清除。</small></label><label v-if="editor==='asset'">到期时间（可选）<input v-model="assetForm.expires_at" type="datetime-local"></label></div><p v-if="message" role="status">{{message}} <code v-if="requestId">{{requestId}}</code></p><footer><button type="submit" :disabled="saving||!assetForm.value">{{saving?'加密写入中…':editor==='rotate'?'确认轮换':'加密保存'}}</button></footer></form><form v-if="editor==='profile'" class="credential-editor" @submit.prevent="saveProfile"><header><div><p>NEW CRAWLER PROFILE</p><h3>创建浏览器档案引用</h3></div><button type="button" @click="editor=null">×</button></header><div class="credential-fields"><label>browser_profile 资产<select v-model="profileForm.credential_asset_id" required @change="profileForm.provider_id=browserAssets.find(x=>x.id===profileForm.credential_asset_id)?.provider_id??''"><option value="" disabled>选择加密档案</option><option v-for="a in browserAssets" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>Code<input v-model="profileForm.code" required pattern="[a-z0-9_]{2,80}"></label><label>名称<input v-model="profileForm.name" required></label><label>Locale<input v-model="profileForm.locale" required></label><label>Timezone<input v-model="profileForm.timezone" required></label><label>状态<select v-model="profileForm.status"><option>disabled</option><option>active</option></select></label></div><p v-if="!browserAssets.length">需要先创建类型为 browser_profile 的 active 凭证资产。</p><footer><button type="submit" :disabled="saving||!browserAssets.length">保存档案引用</button></footer></form><ConfirmDialog :open="Boolean(revokeTarget)" title="确认撤销凭证资产？" :description="`${revokeTarget?.name??''} 撤销后不能轮换或用于新档案。`" impact="只撤销当前平台资产；不会删除历史密文与审计。后续任务必须改用其他已授权凭证。" confirm-label="撤销资产" destructive confirmation-text="确认撤销" @cancel="revokeTarget=null" @confirm="revoke"/></section></template>
